"""Core validation logic for the data_quality package.

The public entry point is :func:`validate`. It validates a list of JSON
object records against a list of rules and returns a result dictionary with
``passed`` / ``summary`` / ``violations``.

Structural problems raise :class:`InvalidInputError` and rule configuration
problems raise :class:`InvalidRuleError`; both subclass :class:`ValueError`.
"""

from __future__ import annotations

import re
from typing import Any, Dict, List

__all__ = [
    "validate",
    "DataQualityError",
    "InvalidInputError",
    "InvalidRuleError",
]

SUPPORTED_TYPES = ("required", "unique", "range", "regex", "allowed_values")

MESSAGES = {
    "required": "is required but is missing or null",
    "unique": "is a duplicate value",
    "range": "is out of the allowed range",
    "regex": "does not match the required pattern",
    "allowed_values": "is not in the list of allowed values",
}


class DataQualityError(ValueError):
    """Base class for validation errors. Carries an CLI error ``code``."""

    code = "INVALID_INPUT"


class InvalidInputError(DataQualityError):
    """The records argument (or the enclosing payload) is malformed."""

    code = "INVALID_INPUT"


class InvalidRuleError(DataQualityError):
    """A rule is malformed, unsupported or has conflicting options."""

    code = "INVALID_RULE"


def _is_number(value: Any) -> bool:
    # bool is a subclass of int, but JSON true/false are not numbers.
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _json_equal(left: Any, right: Any) -> bool:
    """JSON value equality.

    Unlike Python ``==`` this never considers booleans equal to numbers
    (JSON ``true`` is not ``1``) and compares containers structurally.
    """
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(
            _json_equal(a, b) for a, b in zip(left, right)
        )
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(
            _json_equal(left[k], right[k]) for k in left
        )
    return left == right


def _rule_error(message: str) -> InvalidRuleError:
    return InvalidRuleError(message)


def _validate_and_compile_rules(rules: Any) -> List[Dict[str, Any]]:
    if not isinstance(rules, list):
        raise _rule_error("rules must be a list")

    compiled: List[Dict[str, Any]] = []
    seen_ids: set = set()

    for index, rule in enumerate(rules):
        if not isinstance(rule, dict):
            raise _rule_error(f"rules[{index}] must be an object")

        rule_id = rule.get("id")
        if not isinstance(rule_id, str) or not rule_id:
            raise _rule_error(f"rules[{index}] must have a non-empty string id")
        if rule_id in seen_ids:
            raise _rule_error(f"duplicate rule id: {rule_id!r}")
        seen_ids.add(rule_id)

        rule_type = rule.get("type")
        if not isinstance(rule_type, str):
            raise _rule_error(f"rule {rule_id!r} must have a string type")
        if rule_type not in SUPPORTED_TYPES:
            raise _rule_error(
                f"rule {rule_id!r} has unsupported type: {rule_type!r}"
            )

        options = rule.get("options")
        if not isinstance(options, dict):
            raise _rule_error(f"rule {rule_id!r} must have an options object")

        field = options.get("field")
        if not isinstance(field, str):
            raise _rule_error(
                f"rule {rule_id!r}: options.field must be a string"
            )

        allowed_keys = {"field"}
        compiled_rule: Dict[str, Any] = {
            "id": rule_id,
            "type": rule_type,
            "field": field,
        }

        if rule_type == "range":
            allowed_keys |= {"min", "max"}
            minimum = options.get("min")
            maximum = options.get("max")
            if not _is_number(minimum):
                raise _rule_error(
                    f"rule {rule_id!r}: options.min must be a number"
                )
            if not _is_number(maximum):
                raise _rule_error(
                    f"rule {rule_id!r}: options.max must be a number"
                )
            if minimum > maximum:
                raise _rule_error(
                    f"rule {rule_id!r}: options.min ({minimum}) must not be "
                    f"greater than options.max ({maximum})"
                )
            compiled_rule["min"] = minimum
            compiled_rule["max"] = maximum

        elif rule_type == "regex":
            allowed_keys.add("pattern")
            pattern = options.get("pattern")
            if not isinstance(pattern, str):
                raise _rule_error(
                    f"rule {rule_id!r}: options.pattern must be a string"
                )
            try:
                compiled_rule["pattern"] = re.compile(pattern)
            except re.error as exc:
                raise _rule_error(
                    f"rule {rule_id!r}: options.pattern is not a valid "
                    f"regular expression: {exc}"
                ) from exc

        elif rule_type == "allowed_values":
            allowed_keys.add("values")
            values = options.get("values")
            if not isinstance(values, list):
                raise _rule_error(
                    f"rule {rule_id!r}: options.values must be a list"
                )
            compiled_rule["values"] = values

        unknown = set(options) - allowed_keys
        if unknown:
            raise _rule_error(
                f"rule {rule_id!r}: unsupported options for type "
                f"{rule_type!r}: {sorted(unknown)}"
            )

        compiled.append(compiled_rule)

    return compiled


def _violation(rule: Dict[str, Any], index: int, record: Dict[str, Any], value: Any):
    record_id = record["id"] if "id" in record else None
    return {
        "rule_id": rule["id"],
        "record_index": index,
        "record_id": record_id,
        "field": rule["field"],
        "value": value,
        "message": MESSAGES[rule["type"]],
    }


def _check_rule(
    rule: Dict[str, Any],
    records: List[Dict[str, Any]],
    violations: List[Dict[str, Any]],
) -> None:
    rule_type = rule["type"]
    field = rule["field"]

    if rule_type == "unique":
        seen: List[Any] = []

    for index, record in enumerate(records):
        present = field in record
        value = record.get(field)

        if rule_type == "required":
            if not present or value is None:
                violations.append(_violation(rule, index, record, value))

        elif rule_type == "unique":
            # Null values are excluded from uniqueness checks.
            if value is not None:
                if any(_json_equal(value, earlier) for earlier in seen):
                    violations.append(_violation(rule, index, record, value))
                else:
                    seen.append(value)

        elif rule_type == "range":
            if not _is_number(value) or not (
                rule["min"] <= value <= rule["max"]
            ):
                violations.append(_violation(rule, index, record, value))

        elif rule_type == "regex":
            if not isinstance(value, str) or rule["pattern"].fullmatch(value) is None:
                violations.append(_violation(rule, index, record, value))

        elif rule_type == "allowed_values":
            checked = value if present else None
            if not any(_json_equal(checked, allowed) for allowed in rule["values"]):
                violations.append(_violation(rule, index, record, checked))


def validate(
    records: Any,
    rules: Any,
    *,
    dataset: Any = None,
    composite_rules: Any = None,
    record_refs: Any = None,
) -> Dict[str, Any]:
    """Validate ``records`` against single-field ``rules``.

    Rules are fully validated before any record is examined. Rules are then
    evaluated in their given order; within a rule, records are checked in
    order.

    Cross-field composite consistency rules may be supplied via
    ``composite_rules`` (registered and evaluated record by record through
    the public composite entry points). The single-field rules keep their
    existing priority, result structure, sample content and error codes;
    composite results are added separately under ``composite_results`` and
    never alter ``passed`` / ``summary`` / ``violations``. When no
    composite rules are supplied the response is byte-for-byte the
    historical shape.

    :param records: list of JSON objects (plain ``dict`` instances).
    :param rules: list of rule objects with ``id``, ``type`` and ``options``.
    :param dataset: optional dataset identifier used by composite results.
        Required (non-empty string) when ``composite_rules`` is supplied.
    :param composite_rules: optional non-empty list of composite rule
        definitions registered through
        :func:`data_quality.composite.register_composite_rules`.
    :param record_refs: optional record locators restricting composite
        evaluation (see
        :func:`data_quality.composite.evaluate_composite_rules`).
    :returns: ``{"passed": bool, "summary": {...}, "violations": [...]}``
        plus ``composite_results`` when composite rules are supplied.
    :raises ValueError: on malformed input or rule configuration.
    """
    compiled_rules = _validate_and_compile_rules(rules)

    # Register every composite rule (all-or-nothing) before any record is
    # examined or structurally validated, matching the single-field rule
    # priority: a definition whose result cannot be determined aborts the
    # whole validation run.
    composite_rule_set = None
    if composite_rules is not None:
        # Imported lazily to avoid an import cycle between the modules.
        from .composite import register_composite_rules

        composite_rule_set = register_composite_rules(dataset, composite_rules)

    if not isinstance(records, list):
        raise InvalidInputError("records must be a list")
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise InvalidInputError(f"records[{index}] must be a JSON object")

    violations: List[Dict[str, Any]] = []
    for rule in compiled_rules:
        _check_rule(rule, records, violations)

    result: Dict[str, Any] = {
        "passed": not violations,
        "summary": {
            "record_count": len(records),
            "violation_count": len(violations),
            "checked_rule_count": len(compiled_rules),
        },
        "violations": violations,
    }

    if composite_rule_set is not None:
        from .composite import evaluate_composite_rules

        result["composite_rule_count"] = len(composite_rule_set["rules"])
        result["composite_results"] = evaluate_composite_rules(
            records, composite_rule_set, record_refs
        )

    return result

"""Command line interface: ``dq validate``, ``dq lineage``,
``dq field-lineage``, ``dq lineage-paths``, ``dq field-lineage-paths``,
``dq correlate``, ``dq correlate-links``, ``dq violation-origins``,
``dq field-impact``, ``dq query-results``, ``dq snapshot-diff``.

All subcommands read a UTF-8 JSON object from standard input and write a
UTF-8 JSON result to standard output.

``dq validate`` reads ``{"records": [...], "rules": [...], "dataset": ...,
"composite_rules": [...], "record_refs": [...]}`` where ``dataset`` is
required when ``composite_rules`` is present and ``composite_rules`` /
``record_refs`` are optional.
``dq query-results`` reads ``{"results": [...], "rule_id": ...,
"severity": ..., "record_index": ..., "record_id": ...}`` where every
filter is optional.
``dq lineage`` reads ``{"nodes": [...], "edges": [...], "target": ...,
"direction": ..., "max_depth": ...}`` where ``direction`` and ``max_depth``
are optional.
``dq field-lineage`` reads ``{"fields": {...}, "edges": [...], "target": ...,
"direction": ..., "max_depth": ...}`` where ``direction`` and ``max_depth``
are optional.
``dq lineage-paths`` reads the same payload as ``dq lineage`` and explains
the concrete upstream/downstream paths of the target.
``dq field-lineage-paths`` reads the same payload as ``dq field-lineage``
and explains the concrete field-level upstream/downstream paths.
``dq correlate`` reads ``{"results": [...], "lineage": {...}}``.
``dq correlate-links`` reads ``{"results": [...], "lineage": {...},
"sample_links": [...]}``.
``dq violation-origins`` reads ``{"results": [...], "lineage": {...},
"targets": [...]}``.
``dq field-impact`` reads ``{"datasets": {...}, "lineageEdges": [...],
"validationResults": [...], "anomalySamples": {...}, "seedFields": [...]}``.
``dq snapshot-diff`` reads ``{"baseline": {"results": [...]},
"current": {"results": [...]}, "lineage": {...}}`` and consumes already
evaluated check results without re-running any rule.

Error JSON has the shape ``{"error": {"code": ..., "message": ...}}`` and
the process exits with status 2:

* ``INVALID_JSON``                    - stdin is not parseable UTF-8 JSON
* ``INVALID_INPUT``                   - validate payload/records is malformed
* ``INVALID_RULE``                    - a validate rule is malformed/conflicting
* ``INVALID_RULE_SET``                - composite rule set is empty/unusable
* ``DUPLICATE_RULE_ID``               - two composite rules share a rule_id
* ``INVALID_SEVERITY``                - composite rule severity is unknown
* ``UNSUPPORTED_COMPOSITE_CONDITION`` - composite condition type unsupported
* ``INVALID_COMPOSITE_RULE``          - composite rule cannot be executed
                                        (unknown/self-referencing field, bad
                                        date field, malformed condition)
* ``INVALID_RECORD_REFERENCE``        - record locator cannot be resolved
* ``INVALID_LINEAGE_INPUT``           - lineage nodes/edges are missing/malformed
* ``INVALID_LINEAGE_QUERY``           - lineage target/direction/max_depth is bad
* ``UNKNOWN_LINEAGE_TARGET``          - lineage target is not declared in nodes
* ``INVALID_FIELD_LINEAGE_INPUT``     - field-lineage fields/edges are malformed
* ``INVALID_FIELD_LINEAGE_QUERY``     - field-lineage target/direction/max_depth
                                        is invalid
* ``UNKNOWN_FIELD_LINEAGE_TARGET``    - field-lineage target is not declared
* ``LINEAGE_NODE_NOT_FOUND``          - lineage-paths target is not declared
* ``INVALID_CORRELATION_INPUT``       - correlate results/lineage are malformed
* ``UNKNOWN_CORRELATION_REFERENCE``   - correlate result references an
                                        undeclared dataset or field
* ``INVALID_LINKED_CORRELATION_INPUT`` - correlate-links sample_links are
                                         malformed
* ``UNKNOWN_LINKED_CORRELATION_REFERENCE`` - correlate-links sample link
                                            endpoint has no matching result
* ``INVALID_ORIGIN_INPUT``            - violation-origins results/lineage/
                                        targets are malformed
* ``UNKNOWN_ORIGIN_REFERENCE``        - violation-origins result references
                                        an undeclared dataset or field
* ``UNKNOWN_ORIGIN_TARGET``           - violation-origins target has no
                                        matching violated result
* ``INVALID_IMPACT_INPUT``            - field-impact payload structure, key
                                        set, references, rule statuses or
                                        sample mapping is malformed
* ``INVALID_SNAPSHOT_INPUT``          - snapshot-diff snapshots/results/
                                        lineage are malformed
* ``UNKNOWN_SNAPSHOT_REFERENCE``      - snapshot-diff result references an
                                        undeclared dataset or field
"""

from __future__ import annotations

import argparse
import json
import sys
from typing import Any, List, Optional

from .composite import query_composite_results
from .correlation import (
    InvalidCorrelationInputError,
    InvalidLinkedCorrelationInputError,
    UnknownCorrelationReferenceError,
    UnknownLinkedCorrelationReferenceError,
    correlate_linked_violations,
    correlate_violations,
)
from .field_impact import ImpactInputError, analyze_field_impacts
from .field_lineage import (
    InvalidFieldLineageInputError,
    InvalidFieldLineageQueryError,
    UnknownFieldLineageTargetError,
    trace_field_lineage,
)
from .lineage import (
    InvalidLineageInputError,
    InvalidLineageQueryError,
    UnknownLineageTargetError,
    trace_lineage,
)
from .lineage_paths import (
    LineageNodeNotFoundError,
    explain_field_lineage_paths,
    explain_lineage_paths,
)
from .origin_analysis import (
    InvalidOriginInputError,
    UnknownOriginReferenceError,
    UnknownOriginTargetError,
    analyze_violation_origins,
)
from .snapshot_diff import (
    InvalidSnapshotInputError,
    UnknownSnapshotReferenceError,
    compare_quality_snapshots,
)
from .validator import (
    DataQualityError,
    InvalidInputError,
    InvalidRuleError,
    validate,
)

EXIT_OK = 0
EXIT_ERROR = 2

# Sentinel distinguishing "error already emitted" from a parsed payload.
_PARSE_FAILED = object()


def _emit_error(code: str, message: str) -> int:
    payload = {"error": {"code": code, "message": message}}
    json.dump(payload, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_ERROR


def _read_json_payload() -> Any:
    """Read stdin as a UTF-8 JSON value.

    Returns the parsed value, or ``_PARSE_FAILED`` after emitting an
    ``INVALID_JSON`` error.
    """
    raw = sys.stdin.buffer.read()

    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        _emit_error("INVALID_JSON", f"input is not valid UTF-8: {exc}")
        return _PARSE_FAILED

    try:
        return json.loads(text)
    except json.JSONDecodeError as exc:
        _emit_error("INVALID_JSON", f"input is not valid JSON: {exc.msg}")
        return _PARSE_FAILED


def _run_validate() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_INPUT", "input payload must be a JSON object"
        )
    if "records" not in payload:
        return _emit_error("INVALID_INPUT", "payload is missing 'records'")
    if "rules" not in payload:
        return _emit_error("INVALID_INPUT", "payload is missing 'rules'")

    try:
        result = validate(
            payload["records"],
            payload["rules"],
            dataset=payload.get("dataset"),
            composite_rules=payload.get("composite_rules"),
            record_refs=payload.get("record_refs"),
        )
    except InvalidRuleError as exc:
        return _emit_error("INVALID_RULE", str(exc))
    except InvalidInputError as exc:
        return _emit_error("INVALID_INPUT", str(exc))
    except DataQualityError as exc:
        return _emit_error(exc.code, str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_query_results() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_INPUT", "input payload must be a JSON object"
        )
    if "results" not in payload:
        return _emit_error("INVALID_INPUT", "payload is missing 'results'")

    try:
        result = query_composite_results(
            payload["results"],
            rule_id=payload.get("rule_id"),
            severity=payload.get("severity"),
            record_index=payload.get("record_index"),
            record_id=payload.get("record_id"),
        )
    except DataQualityError as exc:
        return _emit_error(exc.code, str(exc))
    except ValueError as exc:
        return _emit_error("INVALID_INPUT", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_lineage() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_LINEAGE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = trace_lineage(
            payload.get("nodes"),
            payload.get("edges"),
            payload.get("target"),
            payload.get("direction", "both"),
            payload.get("max_depth", None),
        )
    except InvalidLineageInputError as exc:
        return _emit_error("INVALID_LINEAGE_INPUT", str(exc))
    except InvalidLineageQueryError as exc:
        return _emit_error("INVALID_LINEAGE_QUERY", str(exc))
    except UnknownLineageTargetError as exc:
        return _emit_error("UNKNOWN_LINEAGE_TARGET", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_field_lineage() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_FIELD_LINEAGE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = trace_field_lineage(
            payload.get("fields"),
            payload.get("edges"),
            payload.get("target"),
            payload.get("direction", "both"),
            payload.get("max_depth", None),
        )
    except InvalidFieldLineageInputError as exc:
        return _emit_error("INVALID_FIELD_LINEAGE_INPUT", str(exc))
    except InvalidFieldLineageQueryError as exc:
        return _emit_error("INVALID_FIELD_LINEAGE_QUERY", str(exc))
    except UnknownFieldLineageTargetError as exc:
        return _emit_error("UNKNOWN_FIELD_LINEAGE_TARGET", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_lineage_paths() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_LINEAGE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = explain_lineage_paths(
            payload.get("nodes"),
            payload.get("edges"),
            payload.get("target"),
            payload.get("direction", "both"),
            payload.get("max_depth", None),
        )
    except InvalidLineageInputError as exc:
        return _emit_error("INVALID_LINEAGE_INPUT", str(exc))
    except InvalidLineageQueryError as exc:
        return _emit_error("INVALID_LINEAGE_QUERY", str(exc))
    except LineageNodeNotFoundError as exc:
        return _emit_error(exc.code, str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_field_lineage_paths() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
