                    ],
                    "customers": [{"id": "c1"}],
                },
                "rules": [ref_rule()],
            }
        )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        lines = proc.stdout.decode("utf-8").splitlines()
        self.assertEqual(len(lines), 1)
        result = json.loads(lines[0])
        self.assertFalse(result["passed"])
        self.assertEqual(
            result["summary"],
            {
                "dataset_count": 2,
                "rule_count": 1,
                "checked_value_count": 2,
                "violation_count": 1,
            },
